CREATE TABLE season_entries(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),plot_id integer REFERENCES plots(id),kind text NOT NULL,title text NOT NULL,data jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'saved',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX season_owner_kind ON season_entries(owner_id,kind);
CREATE TABLE season_events(id uuid PRIMARY KEY,entry_id uuid REFERENCES season_entries(id),actor_id uuid REFERENCES users(id),event text NOT NULL,data jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE rental_extensions(id uuid PRIMARY KEY,user_id uuid REFERENCES users(id),rental_id uuid REFERENCES rentals(id),request_key uuid NOT NULL,months integer NOT NULL CHECK(months BETWEEN 1 AND 12),price_kopecks integer NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(user_id,request_key));
CREATE TABLE garden_groups(id uuid PRIMARY KEY,owner_id uuid REFERENCES users(id),name text NOT NULL);
CREATE TABLE garden_group_plots(group_id uuid REFERENCES garden_groups(id),plot_id integer REFERENCES plots(id),PRIMARY KEY(group_id,plot_id));
CREATE TABLE crop_cycles(id uuid PRIMARY KEY,owner_id uuid REFERENCES users(id),plot_id integer REFERENCES plots(id),crop text NOT NULL,family text NOT NULL,starts_on date NOT NULL,expected_from date,expected_to date,ended_on date,conditions text NOT NULL,approved boolean DEFAULT false,CHECK(expected_to IS NULL OR expected_from IS NOT NULL AND expected_to>=expected_from),CHECK(ended_on IS NULL OR ended_on>=starts_on));
ALTER TABLE harvest_batches ADD COLUMN cycle_id uuid REFERENCES crop_cycles(id);
ALTER TABLE delivery_orders ADD COLUMN packaging text NOT NULL DEFAULT 'standard' CHECK(packaging IN ('standard','returnable','gift'));
ALTER TABLE delivery_orders ADD COLUMN packaging_quote integer CHECK(packaging_quote>=0);
ALTER TABLE work_orders ADD COLUMN customer_verdict text CHECK(customer_verdict IN ('accepted','issue'));
ALTER TABLE work_orders ADD COLUMN customer_comment text;
CREATE TABLE supply_stock(id uuid PRIMARY KEY,owner_id uuid REFERENCES users(id),name text NOT NULL,unit text NOT NULL,balance numeric NOT NULL CHECK(balance>=0),expires_on date);
CREATE TABLE supply_movements(id uuid PRIMARY KEY,supply_id uuid REFERENCES supply_stock(id),actor_id uuid REFERENCES users(id),plot_id integer REFERENCES plots(id),quantity numeric NOT NULL CHECK(quantity>0),reason text NOT NULL,request_key uuid NOT NULL UNIQUE,created_at timestamptz DEFAULT now());
CREATE TABLE seasonal_crop_rules(id uuid PRIMARY KEY,crop text NOT NULL,family text NOT NULL,month_from integer CHECK(month_from BETWEEN 1 AND 12),month_to integer CHECK(month_to BETWEEN 1 AND 12),environment text NOT NULL,days_to_harvest integer CHECK(days_to_harvest>0),spacing_m2 numeric CHECK(spacing_m2>0),water_group text NOT NULL,notes text NOT NULL,enabled boolean DEFAULT true);
ALTER TABLE harvest_batches ADD COLUMN parent_batch_id uuid REFERENCES harvest_batches(id);
CREATE TABLE market_purchases(id uuid PRIMARY KEY,buyer_id uuid REFERENCES users(id),seller_id uuid REFERENCES users(id),listing_id uuid NOT NULL UNIQUE REFERENCES produce_listings(id),batch_id uuid REFERENCES harvest_batches(id),price_kopecks integer NOT NULL,request_key uuid NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(buyer_id,request_key));
ALTER TABLE produce_listings DROP CONSTRAINT produce_listings_status_check;
ALTER TABLE produce_listings ADD CONSTRAINT produce_listings_status_check CHECK(status IN ('active','cancelled','sold'));
ALTER TABLE demo_wallet_entries DROP CONSTRAINT demo_wallet_entries_kind_check;
ALTER TABLE demo_wallet_entries ADD CONSTRAINT demo_wallet_entries_kind_check CHECK(kind IN ('topup','withdraw','payment','refund','subscription','rental','purchase','sale'));
